export const $=s=>document.querySelector(s);
export const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// 商品画像：初期の商品は ./assets、管理画面から登録した画像はサーバー版が uploads/、公開デモはブラウザ内の data URL
const NO_IMAGE='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 150"><rect width="120" height="150" fill="#eef1ec"/><path d="M45 60h30v45H45zM52 52h16v8H52z" fill="#cdd7c9"/></svg>');
export const imageUrl=image=>!image?NO_IMAGE:/^data:image\/(jpeg|png|webp);base64,/.test(image)?image:/^uploads\/products\/[\w-]+\.(jpg|png|webp)$/.test(image)?'./'+image:'./assets/'+image;
export const money=n=>'¥'+Number(n||0).toLocaleString('ja-JP');
export const date=(value,time=false)=>new Date(value).toLocaleString('ja-JP',time?{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}:{year:'numeric',month:'2-digit',day:'2-digit'});
const paths={shield:'M12 3 4 6v6c0 4.6 3.4 8.4 8 9.5 4.6-1.1 8-4.9 8-9.5V6zM9 12l2 2 4-4',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',bag:'M5 7h14l2 14H3L5 7zM8 7V5a4 4 0 0 1 8 0v2',truck:'M2 5h12v12H2zM14 9h4l4 5v3h-8M6 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4M18 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4',box:'m12 2 10 5-10 5L2 7l10-5zM2 7v10l10 5 10-5V7M12 12v10M7 4.5l10 5',store:'M3 10v11h18V10M2 3h20v7a3 3 0 0 1-5 2 3 3 0 0 1-5 0 3 3 0 0 1-5 0 3 3 0 0 1-5-2V3M9 21v-7h6v7',users:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M2 22v-2a7 7 0 0 1 14 0v2M17 4a4 4 0 0 1 0 8M19 16a5 5 0 0 1 3 4v2',wallet:'M3 5h17v16H3V5zM3 5l14-3v3M15 11h7v5h-7v-5z',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M12 6v6l4 2',search:'M10.5 17a6.5 6.5 0 1 0 0-13 6.5 6.5 0 0 0 0 13M16 16l5 5',arrow:'M4 12h16M14 6l6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L20 5',logout:'M9 4H3v16h6M9 12h13M17 7l5 5-5 5',external:'M14 3h7v7M21 3 9 15M10 3H3v18h18v-7',heart:'M12 21 3 12a6 6 0 0 1 9-8 6 6 0 0 1 9 8l-9 9z',refresh:'M20 7A9 9 0 1 0 21 15M20 2v5h-5',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',menu:'M3 6h18M3 12h18M3 18h18',leaf:'M20 3C7 2 1 8 5 16c8 5 15-1 15-13zM4 21 16 8',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M4 22v-2a8 8 0 0 1 16 0v2',x:'M5 5l14 14M5 19 19 5'};
export const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
export const badge=(status,label)=>`<span class="badge status-${esc(status)}"><i></i>${esc(label||status)}</span>`;
let toastTimer;
export function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4200);}
export function modal(title,body,wide=false){const dialog=$('#modal');dialog.classList.toggle('wide',wide);$('#modal-content').innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-close aria-label="閉じる">${icon('x')}</button></div><div class="modal-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
export function closeModal(){$('#modal').close();}
export function empty(title,text='',button=''){return `<div class="empty-state">${icon('bag')}<h3>${esc(title)}</h3><p>${esc(text)}</p>${button}</div>`;}
export function formError(error){const el=$('#form-error');if(el)el.textContent=error.message;else toast(error.message);}
export function downloadCSV(name,headers,rows){const safe=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const blob=new Blob(['\uFEFF'+[headers,...rows].map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
document.addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeModal();});
$('#modal')?.addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
